import json, mpmath as mp
A=json.load(open('arith.json')); B=json.load(open('arith2.json')); Q=json.load(open('quotients.json')); O=json.load(open('order2.json'))
L=[]
def chk(n,c): L.append((bool(c),n)); print(('PASS ' if c else 'FAIL ')+n)
chk('f_3 = 2 - i (Gaussian prime over 5) => eigenvalue sqrt5',A['f3 == 2-i'])
chk('f_4 = 1+2w = i sqrt3 (ramified Eisenstein prime) => eigenvalue sqrt3',A['f4 == 1+2w3 == i*sqrt3'])
chk('f_2 = f_6 = 1',all(A['f6 == 1, f2 == 1']))
chk('f_1,f_5,f_7,f_11 are units of Z[zeta12]; |f_5|^2 = 2+sqrt3 fundamental unit of Q(sqrt3)',A['f1,f5 are units (norm 1)'] and A['|f5|^2 = 2+sqrt3 = fundamental unit of Z[sqrt3]'])
chk('Galois sigma_a f_k = f_{ak}',A['galois sigma_a(f_k)=f_{ak}'])
chk('M11 (complex conjugation) is a graph automorphism (major<->minor)',A['M11 is a graph automorphism of the PLR graph'])
chk('M5,M7 (sigma5,sigma7) map the Tonnetz isomorphically onto the [014] flip graph',A['M5/M7 image set class']=='(0, 1, 4)' and A['flip edges of 014 orbit == M7-induced'])
chk('charpoly = (x-3)(x+3)(x-1)^3(x+1)^3(x^2-5)^2(x^2-3)^2(x^4-4x^2+1)^2',len(A['charpoly factors'])==7)
chk('octic Weil factor T^8+4T^6+9T^4+16T^2+16 irreducible',B['octic irreducible over Q'] and B['octic weil poly']=='T**8 + 4*T**6 + 9*T**4 + 16*T**2 + 16')
for k in ('E+ (lam=1)','E- (lam=-1)','S5 (lam=±sqrt5)','S3 (lam=±sqrt3)'):
    chk(f'{k}: Weil polynomial (all roots |.|=sqrt2)',B[k]['weil'])
chk('E+/E- Frobenius field Q(sqrt-7)',B['E+ (lam=1)']['splits_over_Q_sqrt']==[-7])
chk('S5 field contains Q(sqrt-3) (Eisenstein) and Q(sqrt5)',set(B['S5 (lam=±sqrt5)']['splits_over_Q_sqrt'])=={-3,-15,5})
chk('S3 field Q(sqrt3,sqrt-5)',set(B['S3 (lam=±sqrt3)']['splits_over_Q_sqrt'])=={-5,-15,3})
chk('explicit curves over F2 with trace +1 and -1 exist (brute force)', '1' in B['elliptic curves over F2 by trace a (example [a1,a2,a3,a4,a6])'] and '-1' in B['elliptic curves over F2 by trace a (example [a1,a2,a3,a4,a6])'])
chk('exhaustive: 12 Tonnetz-type homs Z[w]->Z12, all with multiplier-ring conductor 12, none an ideal',Q['n_tonnetz_homs']==12 and Q['multiplier ring conductors over all Tonnetz homs']==[12] and not Q['any kernel an ideal of Z[w]'])
chk('no cyclic Z12 quotient of Z[w], Z[i] (mod 4) or Z[zeta12] (mod 3, mod 4)',Q['x^2+x+1 roots mod 4']==[] and Q['x^2+1 roots mod 4 (Z4 as Z[i]-quotient?)']==[] and Q['Phi12 = x^4-x^2+1 roots mod 4, mod 3']==[[],[]])
chk('orders Z[f w] with cyclic Z12 quotient: exactly even f (f<=12)',O['conductors f<=12 with cyclic Z12 quotient ring']==[2,4,6,8,10,12])
chk('Tonnetz = Z[sqrt-3]/(sqrt-3 (1+sqrt-3)): fifth=1+2s, M3=1+s, m3=s, semitone=1',O['psi o phi == 7a+4b'] and O['ker psi is ideal of Z[sqrt-3]'] and O['J == (3-sqrt-3), norm 12'] and O['basis unimodular (det)'] in (1,-1))
chk('that CM torus is C/Z[sqrt-3], j = 54000',abs(complex(O['j(sqrt(-3))'].replace(' ','').replace('j','j'))-54000)<1e-6 if False else O['j(sqrt(-3))'].startswith('(54000.0'))
chk('equilateral (musical) Tonnetz torus: reduced form (9,-6,13), disc -432',tuple(Q['reduced period form'])==(9,-6,13) and Q['disc']==-432)
n=sum(p for p,_ in L); print(f'PASS {n}/{len(L)}')
open('math_audit.md','w').write(f'# Stage 1 (Eisenstein, new angles) audit — {n}/{len(L)} PASS\n\n'+'\n'.join(f"- {'PASS' if p else 'FAIL'} {s}" for p,s in L)+'\n\nExternal (LMFDB, fetched 2026-11-25): 1.2.ab (y^2+xy=x^3+x^2+1, Q(sqrt-7)), 1.2.b (y^2+xy=x^3+1), 2.2.a_ab (Jacobian of y^2+(x^2+x)y=x^5+x^3+x^2+x, End Q(sqrt-3,sqrt5), over F4 ~ (1.4.ab)^2 with M2(Q(sqrt-15))), 2.2.a_b (Jacobian of y^2+(x^2+x+1)y=x^5+x^3+x^2+1, End Q(sqrt3,sqrt-5), over F4 ~ (1.4.b)^2), 4.2.a_e_a_j (no Jacobian, field 8.0.5780865024.4), newform 49.2.a.a (CM -7, a_2 = 1).\n')
